    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    l = int(data[2])
    MOD = int(data[3])

    if k >= (1 << l):
        print(0)
        return

    memo = {0: 1, 1: 1}
    def fib(n):
        if n in memo:
            return memo[n]
        k = n // 2
        if n % 2 == 0:
            res = (fib(k) * fib(k) + fib(k-1) * fib(k-1)) % MOD
        else:
            res = (fib(k) * fib(k+1) + fib(k-1) * fib(k)) % MOD
        memo[n] = res
        return res

    zeroPos = fib(n + 1)
    onePos = (pow(2, n, MOD) - zeroPos) % MOD

    res = 1
    for i in range(l):
        if (k >> i) & 1:
            res = (res * onePos) % MOD
        else:
            res = (res * zeroPos) % MOD
    print(res % MOD)

